import React, { useMemo, useState } from 'react';
import LogFilterBar from '../../components/logs/LogFilterBar';
import LogTable from '../../components/logs/LogTable';
import LogDetailModal from '../../components/logs/LogDetailModal';
import { useLogs } from '../../hooks/UseLogs';

function LogsPage() {
  const {
    logs,
    loading,
    error,
    page,
    setPage,
    size,
    setSize,
    total,
    filters,
    setFilters,
    refresh,
    search,
  } = useLogs(50);

  const [selectedLog, setSelectedLog] = useState(null);

  // ✅ (중요) 지금은 백엔드 /logs가 없을 수 있어서
  // fallback(/logs/recent)은 서버 필터가 안 먹음.
  // 따라서 "표시용"으로만 최소 필터링을 한 번 더 적용해줌.
  const visibleLogs = useMemo(() => {
    const keyword = (filters.keyword || '').trim().toLowerCase();
    const aiLabel = filters.aiLabel;

    return (logs || []).filter((log) => {
      const matchKeyword =
        !keyword ||
        String(log.path || '').toLowerCase().includes(keyword) ||
        String(log.eventType || '').toLowerCase().includes(keyword) ||
        String(log.aiDetail || '').toLowerCase().includes(keyword);

      const matchLabel = !aiLabel || log.aiLabel === aiLabel;

      return matchKeyword && matchLabel;
    });
  }, [logs, filters.keyword, filters.aiLabel]);

  const handleSelectLog = (log) => setSelectedLog(log);
  const handleCloseModal = () => setSelectedLog(null);

  const handleKeywordChange = (val) => {
    setFilters((p) => ({ ...p, keyword: val }));
  };

  const handleRiskFilterChange = (val) => {
    // LogFilterBar는 "ALL/DANGER/WARNING/SAFE"를 쓰고 있음 :contentReference[oaicite:0]{index=0}
    const aiLabel = val === 'ALL' ? '' : val;
    setFilters((p) => ({ ...p, aiLabel }));
  };

  const handleSearch = () => {
    // ✅ 서버 /logs 구현되면 여기서부터는 서버 검색으로 동작
    // fallback(/logs/recent)일 때는 visibleLogs가 한번 더 걸러줌
    search();
  };

  return (
    <div className="page-container">
      <h1>로그 관리</h1>

      {/* 필터/검색 바 */}
      <LogFilterBar
        keyword={filters.keyword}
        setKeyword={handleKeywordChange}
        riskFilter={filters.aiLabel || 'ALL'}   // ''이면 ALL로 보이게
        setRiskFilter={(v) => handleRiskFilterChange(v)}
        refreshLogs={refresh}
      />

      {/* 페이지/사이즈(간단) */}
      <div style={{ display: 'flex', gap: 8, alignItems: 'center', margin: '12px 0' }}>
        <button className="btn" onClick={handleSearch}>
          검색 적용
        </button>

        <select value={size} onChange={(e) => setSize(Number(e.target.value) || 50)}>
          <option value={20}>20</option>
          <option value={50}>50</option>
          <option value={100}>100</option>
        </select>

        <button className="btn" onClick={() => setPage((p) => Math.max(1, p - 1))}>
          이전
        </button>
        <span>page: {page}</span>
        <button className="btn" onClick={() => setPage((p) => p + 1)}>
          다음
        </button>

        {total != null && (
          <span style={{ marginLeft: 8, color: '#9ca3af' }}>
            total: {total}
          </span>
        )}
      </div>

      {loading && <p>불러오는 중...</p>}
      {error && <p style={{ color: 'red' }}>오류: {error.message}</p>}

      {!loading && !error && (
        <LogTable logs={visibleLogs} onSelectLog={handleSelectLog} />
      )}

      {selectedLog && <LogDetailModal log={selectedLog} onClose={handleCloseModal} />}
    </div>
  );
}

export default LogsPage;
